import React, { useState, useEffect } from 'react';
import { dashboardApi } from '../api/client';
import SkeletonCard from './SkeletonCard';
import EmptyState from './EmptyState';
import { AlertOctagon, AlertTriangle, Info, CheckCircle2, ShieldAlert } from 'lucide-react';

const AlertsPanel = () => {
  const [alerts, setAlerts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [ackLoadingId, setAckLoadingId] = useState(null);

  useEffect(() => {
    fetchActiveAlerts();
  }, []);

  const fetchActiveAlerts = async () => {
    try {
      setLoading(true);
      const res = await dashboardApi.getActiveAlerts();
      if (res.data.success) {
        setAlerts(res.data.data);
      }
    } catch (err) {
      console.error('Failed to fetch active alerts:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleAcknowledge = async (alertId) => {
    try {
      setAckLoadingId(alertId);
      const res = await dashboardApi.acknowledgeAlert(alertId);
      if (res.data.success) {
        // Remove from list
        setAlerts((prev) => prev.filter((a) => (a._id || a.id) !== alertId));
      }
    } catch (err) {
      console.error('Failed to acknowledge alert:', err);
    } finally {
      setAckLoadingId(null);
    }
  };

  const getSeverityIcon = (severity) => {
    switch (severity) {
      case 'critical':
        return <AlertOctagon size={18} style={{ color: 'var(--status-maintenance)' }} />;
      case 'maintenance':
        return <AlertTriangle size={18} style={{ color: 'var(--status-idle)' }} />;
      default:
        return <Info size={18} style={{ color: 'var(--accent-primary)' }} />;
    }
  };

  const formatTimeAgo = (dateStr) => {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    const now = new Date();
    const diffMins = Math.floor((now - date) / (1000 * 60));
    if (diffMins < 1) return 'Just now';
    if (diffMins < 60) return `${diffMins} mins ago`;
    const diffHours = Math.floor(diffMins / 60);
    return `${diffHours} hour${diffHours > 1 ? 's' : ''} ago`;
  };

  if (loading) return <SkeletonCard height="280px" />;

  return (
    <div className="glass-card" style={{ padding: '1.5rem', display: 'flex', flexDirection: 'column' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
        <div>
          <h3 style={{ fontSize: '1.05rem', fontWeight: '700', color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <ShieldAlert size={18} style={{ color: 'var(--status-maintenance)' }} /> Active Sensor Alerts
          </h3>
          <span style={{ fontSize: '0.78rem', color: 'var(--text-secondary)' }}>Real-Time Machinery Anomalies ({alerts.length} Unresolved)</span>
        </div>
      </div>

      {alerts.length === 0 ? (
        <EmptyState
          title="No Alerts Right Now"
          message="All loom sensors are operating within optimal parameters."
          icon={CheckCircle2}
        />
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.85rem' }}>
          {alerts.map((alert) => {
            const id = alert._id || alert.id;
            return (
              <div
                key={id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: '1rem',
                  padding: '0.9rem 1.1rem',
                  borderRadius: 'var(--radius-sm)',
                  background: alert.severity === 'critical' ? 'var(--status-maintenance-bg)' : 'var(--status-idle-bg)',
                  border: `1px solid ${alert.severity === 'critical' ? 'rgba(239,68,68,0.25)' : 'rgba(245,158,11,0.25)'}`,
                }}
              >
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.85rem' }}>
                  {getSeverityIcon(alert.severity)}
                  <div>
                    <div style={{ fontSize: '0.88rem', fontWeight: '600', color: 'var(--text-primary)' }}>
                      {alert.message}
                    </div>
                    <div style={{ fontSize: '0.78rem', color: 'var(--text-secondary)', marginTop: '0.2rem', display: 'flex', gap: '0.5rem', alignItems: 'center' }}>
                      <span style={{ color: 'var(--accent-primary)', fontWeight: '600' }}>{alert.machineName || alert.machineId}</span>
                      <span>•</span>
                      <span>{formatTimeAgo(alert.triggeredAt)}</span>
                    </div>
                  </div>
                </div>

                <button
                  className="btn btn-secondary btn-sm"
                  onClick={() => handleAcknowledge(id)}
                  disabled={ackLoadingId === id}
                  style={{ whiteSpace: 'nowrap' }}
                >
                  {ackLoadingId === id ? 'Acking...' : 'Acknowledge'}
                </button>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default AlertsPanel;
